function initials(name: string) {
  return name.split(" ").map(part => part[0]).join("").slice(0, 2).toUpperCase();
}

function validatePassword(value: string) {
  if (value.length < 8 || value.length > 16) return "Use 8–16 characters.";
  if (!/[A-Z]/.test(value)) return "Add at least one uppercase letter.";
  if (!/[^A-Za-z0-9]/.test(value)) return "Add at least one special character.";
  return "";
}

function Stars({ value, onChange, size = 16 }: { value: number; onChange?: (value: number) => void; size?: number }) {
  return <div className="flex items-center gap-0.5" aria-label={`${value} out of 5 stars`}>
    {[1, 2, 3, 4, 5].map(star => <button key={star} type="button" aria-label={`${star} star${star > 1 ? "s" : ""}`} onClick={() => onChange?.(star)} className={`${onChange ? "hover:scale-110" : "pointer-events-none"} p-0.5 text-transparent transition-transform`} style={{ width: size + 4, height: size + 4 }}>
      <Star size={size} strokeWidth={1.8} className={star <= value ? "fill-[#E86B4F] text-[#E86B4F]" : "text-[#CBD2D5]"} />
    </button>)}
  </div>;
}

function RolePill({ role }: { role: Role }) {
  const copy = role === "storeOwner" ? "Store owner" : role === "admin" ? "Administrator" : "Normal user";
  const style = role === "admin" ? "bg-[#FFF0EB] text-[#C54A31]" : role === "storeOwner" ? "bg-[#EAF5F1] text-[#167469]" : "bg-[#EEF2FF] text-[#5267B9]";
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold tracking-wide ${style}`}>{copy}</span>;
}

function Button({ children, variant = "primary", className = "", onClick, type = "button", disabled = false }: { children: React.ReactNode; variant?: "primary" | "ghost" | "outline" | "soft"; className?: string; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean }) {
  const styles = {
    primary: "bg-[#172235] text-white shadow-[0_5px_14px_rgba(23,34,53,.13)] hover:bg-[#24334e]",
    ghost: "text-[#6F7C90] hover:bg-[#F1F3F4] hover:text-[#172235]",
    outline: "border border-[#DCE1E3] bg-white text-[#344054] hover:border-[#B9C3C6] hover:bg-[#FAFBFA]",
    soft: "bg-[#FFF0EB] text-[#C84F38] hover:bg-[#FFE5DE]",
  };
  return <button type={type} disabled={disabled} onClick={onClick} className={`inline-flex min-h-10 items-center justify-center gap-2 rounded-xl px-4 text-sm font-bold disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}

function Field({ label, value, onChange, placeholder, type = "text", error, hint, required = false }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string; type?: string; error?: string; hint?: string; required?: boolean }) {
  return <label className="block space-y-1.5">
    <span className="flex items-center justify-between text-xs font-bold text-[#46546A]">{label}{required && <span className="text-[#E86B4F]">Required</span>}</span>
    <input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} type={type} className={`h-11 w-full rounded-xl border bg-white px-3.5 text-sm text-[#172235] outline-none transition placeholder:text-[#A0AAB4] focus:border-[#E86B4F] focus:ring-4 focus:ring-[#E86B4F]/10 ${error ? "border-[#E86B4F]" : "border-[#DFE4E6]"}`} />
    {error ? <span className="block text-xs font-medium text-[#C84F38]">{error}</span> : hint ? <span className="block text-[11px] text-[#8B97A8]">{hint}</span> : null}
  </label>;
}

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-2.5">
    <div className="grid h-9 w-9 place-items-center rounded-xl bg-[#E86B4F] text-white shadow-[0_4px_12px_rgba(232,107,79,.24)]"><Sparkles size={18} strokeWidth={2.5} /></div>
    {!compact && <div><div className="font-display text-[15px] font-bold tracking-tight text-[#172235]">Ratings<span className="text-[#E86B4F]">Hub</span></div><div className="text-[9px] font-bold uppercase tracking-[.16em] text-[#9AA5AB]">Community signal</div></div>}
  </div>;
}

function AuthScreen({ onLogin }: { onLogin: (user: AppUser) => void }) {
  const [mode, setMode] = useState<"login" | "signup">("login");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [name, setName] = useState("");
  const [address, setAddress] = useState("");
  const [error, setError] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    setError("");
    if (!email.includes("@")) return setError("Enter a valid email address.");
    const passwordError = validatePassword(password);
    if (passwordError) return setError(passwordError);
    if (mode === "signup") {
      if (name.trim().length < 20) return setError("Name must be between 20 and 60 characters.");
      if (address.length > 400) return setError("Address must be 400 characters or less.");
      onLogin({ id: 100, name: name.trim(), email: email.toLowerCase(), address, role: "user", initials: initials(name) });
      return;
    }
    const match = Object.values(demoUsers).find(user => user.email === email.toLowerCase());
    if (!match) return setError("For this review build, use one of the demo emails below.");
    onLogin(match);
  };
  const quick = (role: Role) => { const user = demoUsers[role]; setEmail(user.email); setPassword(role === "admin" ? "Admin@123" : role === "storeOwner" ? "Owner@123" : "Welcome@1"); onLogin(user); };
  return <div className="min-h-screen overflow-hidden bg-[#172235] text-white">
    <div className="grid min-h-screen lg:grid-cols-[1.05fr_.95fr]">
      <section className="relative hidden overflow-hidden lg:flex lg:flex-col lg:justify-between bg-[#172235] p-12 xl:p-16">
        <div className="absolute -right-28 -top-24 h-96 w-96 rounded-full border-[1px] border-white/10" /><div className="absolute -bottom-44 -left-20 h-[34rem] w-[34rem] rounded-full border-[1px] border-white/10" />
        <div><Logo compact /><div className="mt-24 max-w-xl"><div className="mb-5 inline-flex items-center gap-2 rounded-full border border-[#E86B4F]/40 bg-[#E86B4F]/10 px-3 py-1.5 text-xs font-bold text-[#FFB6A5]"><span className="h-1.5 w-1.5 rounded-full bg-[#E86B4F]" /> Built for better local decisions</div><h1 className="font-display text-5xl font-bold leading-[1.05] tracking-[-.045em] xl:text-6xl">A clearer signal<br /><span className="text-[#F39A82]">for every place.</span></h1><p className="mt-7 max-w-md text-base leading-7 text-[#AAB6C6]">RatingsHub gives people, owners, and admins one calm place to turn everyday feedback into momentum.</p></div></div>
        <div className="relative"><div className="flex items-end gap-3"><div className="rounded-2xl border border-white/10 bg-white/5 p-4 backdrop-blur"><div className="text-[11px] font-bold uppercase tracking-[.16em] text-[#8F9CAF]">Places rated this week</div><div className="mt-2 font-display text-3xl font-bold">2,468</div><div className="mt-2 flex items-center gap-1 text-xs font-bold text-[#8DD2BE]"><ArrowUpAZ size={13} /> 18.4%</div></div><div className="mb-3 rounded-2xl border border-[#E86B4F]/30 bg-[#E86B4F] p-4"><Star size={18} className="fill-white" /><div className="mt-5 font-display text-2xl font-bold">4.7</div><div className="mt-1 text-[11px] text-white/70">community average</div></div></div><p className="mt-7 text-xs text-[#768397]">Trusted by teams who care about the details.</p></div>
      </section>
      <section className="flex min-h-screen flex-col bg-[#FAF9F6] px-5 py-7 text-[#172235] sm:px-10 lg:px-16 lg:py-12"><div className="flex items-center justify-between lg:justify-end"><div className="lg:hidden"><Logo /></div><div className="text-xs font-semibold text-[#8C98A6]">{mode === "login" ? "New to RatingsHub?" : "Already have access?"} <button className="ml-1 font-bold text-[#C84F38]" onClick={() => { setMode(mode === "login" ? "signup" : "login"); setError(""); }}>{mode === "login" ? "Create account" : "Sign in"}</button></div></div><div className="mx-auto flex w-full max-w-md flex-1 flex-col justify-center py-10"><div className="mb-8"><div className="mb-4 inline-flex rounded-xl bg-[#FFF0EB] p-3 text-[#E86B4F]"><ShieldCheck size={21} /></div><h2 className="font-display text-3xl font-bold tracking-[-.035em]">{mode === "login" ? "Welcome back" : "Join the signal"}</h2><p className="mt-2 text-sm leading-6 text-[#7C8797]">{mode === "login" ? "Sign in to see what your community is saying." : "Create a normal user account to start rating stores."}</p></div><form onSubmit={submit} className="space-y-4">{mode === "signup" && <><Field label="Full name" value={name} onChange={setName} placeholder="At least 20 characters" required error={name && name.trim().length < 20 ? "20 characters minimum" : undefined} /><Field label="Address" value={address} onChange={setAddress} placeholder="Street, city, state" required /></>}<Field label="Email" value={email} onChange={setEmail} placeholder="you@example.com" type="email" required /><div className="relative"><Field label="Password" value={password} onChange={setPassword} placeholder="8–16 chars, uppercase + special" type={showPassword ? "text" : "password"} required hint="Must include an uppercase letter and special character." /><button type="button" className="absolute right-3 top-8 text-[#97A1AD]" onClick={() => setShowPassword(!showPassword)}>{showPassword ? "Hide" : "Show"}</button></div>{error && <div className="rounded-xl border border-[#F4C7BB] bg-[#FFF2EF] px-3.5 py-3 text-xs font-semibold text-[#C84F38]">{error}</div>}<Button type="submit" className="mt-1 w-full">{mode === "login" ? "Sign in to workspace" : "Create my account"}<ChevronRight size={16} /></Button></form>{mode === "login" && <><div className="my-7 flex items-center gap-3 text-[10px] font-bold uppercase tracking-[.18em] text-[#A2ACB4]"><span className="h-px flex-1 bg-[#E5E6E4]" /> Demo access <span className="h-px flex-1 bg-[#E5E6E4]" /></div><div className="grid grid-cols-3 gap-2"><button onClick={() => quick("admin")} className="rounded-xl border border-[#E1E5E5] bg-white p-3 text-left hover:border-[#E86B4F]"><div className="mb-3 grid h-7 w-7 place-items-center rounded-lg bg-[#FFF0EB] text-[#C84F38]"><ShieldCheck size={14} /></div><div className="text-[11px] font-bold">Admin</div><div className="mt-0.5 text-[10px] text-[#98A2AC]">Full access</div></button><button onClick={() => quick("user")} className="rounded-xl border border-[#E1E5E5] bg-white p-3 text-left hover:border-[#E86B4F]"><div className="mb-3 grid h-7 w-7 place-items-center rounded-lg bg-[#EEF2FF] text-[#5267B9]"><Users size={14} /></div><div className="text-[11px] font-bold">Normal user</div><div className="mt-0.5 text-[10px] text-[#98A2AC]">Rate stores</div></button><button onClick={() => quick("storeOwner")} className="rounded-xl border border-[#E1E5E5] bg-white p-3 text-left hover:border-[#E86B4F]"><div className="mb-3 grid h-7 w-7 place-items-center rounded-lg bg-[#EAF5F1] text-[#167469]"><Store size={14} /></div><div className="text-[11px] font-bold">Owner</div><div className="mt-0.5 text-[10px] text-[#98A2AC]">View insights</div></button></div></>}</div><div className="text-center text-[11px] text-[#A1AAB2]">By continuing, you agree to our <span className="font-bold text-[#6F7B8B]">community guidelines</span>.</div></section>
    </div>
  </div>;
}

function Sidebar({ user, view, setView, onLogout, mobileOpen, setMobileOpen }: { user: AppUser; view: View; setView: (view: View) => void; onLogout: () => void; mobileOpen: boolean; setMobileOpen: (value: boolean) => void }) {
  const items = user.role === "admin" ? [{ label: "Overview", value: "overview" as View, icon: LayoutDashboard }, { label: "Stores", value: "stores" as View, icon: Store }, { label: "People", value: "people" as View, icon: Users }] : user.role === "storeOwner" ? [{ label: "Overview", value: "overview" as View, icon: LayoutDashboard }, { label: "Reviews", value: "reviews" as View, icon: ClipboardList }] : [{ label: "Discover stores", value: "discover" as View, icon: Store }, { label: "My activity", value: "activity" as View, icon: BarChart3 }];
  return <><aside className={`${mobileOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0"} fixed inset-y-0 left-0 z-30 flex w-[248px] flex-col border-r border-[#E7E9E7] bg-white px-4 py-5 transition-transform lg:static`}><div className="flex items-center justify-between px-2"><Logo /><button className="rounded-lg p-2 text-[#94A0AE] lg:hidden" onClick={() => setMobileOpen(false)}><X size={18} /></button></div><div className="mt-10 px-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#A4ACB3]">Workspace</div><nav className="mt-3 space-y-1">{items.map(item => { const Icon = item.icon; return <button key={item.value} onClick={() => { setView(item.value); setMobileOpen(false); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-bold ${view === item.value ? "bg-[#FFF0EB] text-[#C84F38]" : "text-[#738094] hover:bg-[#F6F7F6] hover:text-[#172235]"}`}><Icon size={17} strokeWidth={2} /><span>{item.label}</span>{view === item.value && <ChevronRight size={14} className="ml-auto" />}</button>; })}</nav><div className="mt-8 px-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#A4ACB3]">Account</div><nav className="mt-3 space-y-1"><button onClick={() => { setView("settings"); setMobileOpen(false); }} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-bold ${view === "settings" ? "bg-[#FFF0EB] text-[#C84F38]" : "text-[#738094] hover:bg-[#F6F7F6] hover:text-[#172235]"}`}><Settings size={17} /><span>Settings</span></button><button onClick={onLogout} className="flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-bold text-[#738094] hover:bg-[#FDEDEC] hover:text-[#C84F38]"><LogOut size={17} /><span>Log out</span></button></nav><div className="mt-auto rounded-2xl bg-[#F5F7F6] p-3.5"><div className="flex items-center gap-2.5"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#172235] text-[11px] font-bold text-white">{user.initials}</div><div className="min-w-0"><div className="truncate text-xs font-bold text-[#172235]">{user.name}</div><div className="mt-0.5 truncate text-[10px] text-[#8D98A5]">{user.email}</div></div></div><div className="mt-3"><RolePill role={user.role} /></div></div></aside>{mobileOpen && <button aria-label="Close navigation" className="fixed inset-0 z-20 bg-[#172235]/25 lg:hidden" onClick={() => setMobileOpen(false)} />}</>;
}

function Topbar({ user, onOpenMenu }: { user: AppUser; onOpenMenu: () => void }) {
  const label = user.role === "admin" ? "Admin workspace" : user.role === "storeOwner" ? "Owner workspace" : "Your rating journey";
  return <header className="flex h-[76px] items-center justify-between border-b border-[#E7E9E7] bg-white/80 px-5 backdrop-blur sm:px-8"><div className="flex items-center gap-3"><button onClick={onOpenMenu} className="rounded-xl border border-[#E5E8E7] p-2 text-[#6D7B8B] lg:hidden"><Menu size={18} /></button><div><div className="text-[11px] font-bold uppercase tracking-[.16em] text-[#9AA4AF]">{label}</div><div className="mt-0.5 font-display text-lg font-bold text-[#172235]">Good morning, {user.name.split(" ")[0]} <span className="text-[#E86B4F]">·</span></div></div></div><div className="flex items-center gap-3"><button className="relative hidden rounded-xl border border-[#E5E8E7] bg-white p-2.5 text-[#738094] hover:bg-[#F8F9F8] sm:block"><CircleHelp size={17} /><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-[#E86B4F]" /></button><div className="hidden h-7 w-px bg-[#E5E8E7] sm:block" /><div className="grid h-9 w-9 place-items-center rounded-full bg-[#FCE5DE] text-xs font-bold text-[#C84F38]">{user.initials}</div></div></header>;
}

function PageHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: React.ReactNode }) {
  return <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.2em] text-[#E86B4F]">{eyebrow}</div><h1 className="font-display text-[30px] font-bold tracking-[-.04em] text-[#172235]">{title}</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-[#7C8898]">{copy}</p></div>{action}</div>;
}

function StatCard({ label, value, trend, detail, icon: Icon, accent }: { label: string; value: string; trend?: string; detail: string; icon: any; accent: "coral" | "teal" | "blue" }) {
  const colors = { coral: "bg-[#FFF0EB] text-[#C84F38]", teal: "bg-[#EAF5F1] text-[#167469]", blue: "bg-[#EEF2FF] text-[#5267B9]" };
  return <div className="rounded-2xl border border-[#E6E9E7] bg-white p-5 shadow-[0_10px_30px_rgba(23,34,53,.035)]"><div className="flex items-start justify-between"><div className={`grid h-10 w-10 place-items-center rounded-xl ${colors[accent]}`}><Icon size={19} /></div>{trend && <span className="rounded-full bg-[#EAF5F1] px-2 py-1 text-[10px] font-bold text-[#167469]">{trend}</span>}</div><div className="mt-5 font-display text-3xl font-bold tracking-[-.04em] text-[#172235]">{value}</div><div className="mt-1 text-xs font-bold text-[#667488]">{label}</div><div className="mt-3 text-[11px] text-[#9AA4AF]">{detail}</div></div>;
}

function AdminOverview({ stores, people, setView }: { stores: StoreRecord[]; people: AppUser[]; setView: (view: View) => void }) {
  const maxRating = Math.max(...stores.map(s => s.rating));
  return <div className="space-y-7 animate-float-in"><PageHeading eyebrow="System administrator" title="Command center" copy="A quick pulse on platform health, community activity, and your highest-rated places." action={<Button variant="outline" onClick={() => setView("stores")}><SlidersHorizontal size={15} /> Manage data</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Total users" value="1,284" trend="+12.8%" detail="vs. last 30 days" icon={Users} accent="blue" /><StatCard label="Registered stores" value={String(stores.length + 40)} trend="+8.4%" detail="7 added this month" icon={Store} accent="coral" /><StatCard label="Ratings submitted" value="8,692" trend="+18.4%" detail="Across all locations" icon={Star} accent="teal" /><StatCard label="Avg. platform rating" value="4.6" detail="From 8,692 responses" icon={BarChart3} accent="coral" /></div><div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><section className="rounded-2xl border border-[#E6E9E7] bg-white p-5 shadow-[0_10px_30px_rgba(23,34,53,.035)]"><div className="flex items-start justify-between"><div><h2 className="font-display text-base font-bold">Rating activity</h2><p className="mt-1 text-xs text-[#8A96A5]">Submissions over the last 7 days</p></div><select className="rounded-lg border border-[#E5E8E7] bg-white px-2 py-1.5 text-xs font-bold text-[#667488]"><option>Last 7 days</option><option>Last 30 days</option></select></div><div className="mt-7 flex h-48 items-end gap-3 border-b border-l border-[#E9ECEB] px-4 pb-0 sm:gap-6"><div className="pointer-events-none absolute" />{[{d:"Mon",n:62},{d:"Tue",n:78},{d:"Wed",n:54},{d:"Thu",n:91},{d:"Fri",n:83},{d:"Sat",n:97},{d:"Sun",n:72}].map((bar, index) => <div key={bar.d} className="flex h-full flex-1 flex-col items-center justify-end gap-2"><div className={`w-full max-w-8 rounded-t-lg ${index === 5 ? "bg-[#E86B4F]" : "bg-[#F7C5B8]"}`} style={{ height: `${bar.n}%` }} title={`${bar.n} ratings`} /><span className="mb-[-22px] text-[10px] font-bold text-[#A2ACB5]">{bar.d}</span></div>)}</div><div className="mt-7 grid grid-cols-3 gap-4 border-t border-[#EEF0EF] pt-4"><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-[#A1AAB3]">Today</div><div className="mt-1 font-display text-lg font-bold">128</div></div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-[#A1AAB3]">Peak hour</div><div className="mt-1 font-display text-lg font-bold">6–7 PM</div></div><div><div className="text-[10px] font-bold uppercase tracking-[.12em] text-[#A1AAB3]">Completion</div><div className="mt-1 font-display text-lg font-bold">94%</div></div></div></section><section className="rounded-2xl border border-[#E6E9E7] bg-[#172235] p-5 text-white shadow-[0_10px_30px_rgba(23,34,53,.09)]"><div className="flex items-center justify-between"><div><h2 className="font-display text-base font-bold">Top stores</h2><p className="mt-1 text-xs text-[#93A0B1]">By community rating</p></div><button onClick={() => setView("stores")} className="text-xs font-bold text-[#F5A28F]">View all</button></div><div className="mt-5 space-y-4">{stores.slice(0, 4).map((store, index) => <div key={store.id} className="flex items-center gap-3"><div className="grid h-8 w-8 place-items-center rounded-lg bg-white/10 text-[11px] font-bold text-[#B8C3D0]">0{index + 1}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{store.name}</div><div className="mt-1 flex items-center gap-1.5 text-[10px] text-[#93A0B1]"><Stars value={Math.round(store.rating)} size={11} /><span>{store.rating.toFixed(1)}</span></div></div><div className="text-[10px] text-[#8290A2]">{store.ratingCount} votes</div></div>)}</div></section></div><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><section className="rounded-2xl border border-[#E6E9E7] bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="font-display text-base font-bold">Role mix</h2><p className="mt-1 text-xs text-[#8A96A5]">People by access level</p></div><Users size={18} className="text-[#A4AFB8]" /></div><div className="mt-6 space-y-4">{[{role:"Normal users",count:1182,color:"bg-[#6E83D8]"},{role:"Store owners",count:76,color:"bg-[#E86B4F]"},{role:"Administrators",count:26,color:"bg-[#35A08E]"}].map(item => <div key={item.role}><div className="mb-2 flex justify-between text-xs"><span className="font-bold text-[#526073]">{item.role}</span><span className="font-bold text-[#172235]">{item.count}</span></div><div className="h-2 overflow-hidden rounded-full bg-[#EEF1F1]"><div className={`h-full rounded-full ${item.color}`} style={{ width: `${(item.count / 1284) * 100}%` }} /></div></div>)}</div></section><section className="rounded-2xl border border-[#E6E9E7] bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="font-display text-base font-bold">Recently joined</h2><p className="mt-1 text-xs text-[#8A96A5]">Latest accounts on the platform</p></div><button onClick={() => setView("people")} className="text-xs font-bold text-[#C84F38]">See directory</button></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{people.slice(0, 4).map(person => <div key={person.id} className="flex items-center gap-3 rounded-xl bg-[#F8F9F8] p-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#E8EDF1] text-[10px] font-bold text-[#54657A]">{person.initials}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{person.name}</div><div className="mt-0.5 truncate text-[10px] text-[#93A0AB]">{person.email}</div></div><RolePill role={person.role} /></div>)}</div></section></div></div>;
}

function AdminDirectory({ stores, people, setStores, setPeople, initialTab = "stores", toast }: { stores: StoreRecord[]; people: AppUser[]; setStores: React.Dispatch<React.SetStateAction<StoreRecord[]>>; setPeople: React.Dispatch<React.SetStateAction<AppUser[]>>; initialTab?: "stores" | "people"; toast: (message: string) => void }) {
  const [tab, setTab] = useState(initialTab); const [query, setQuery] = useState(""); const [role, setRole] = useState<"all" | Role>("all"); const [sortAsc, setSortAsc] = useState(true); const [modal, setModal] = useState<"store" | "user" | null>(null); const [selected, setSelected] = useState<AppUser | null>(null);
  const [newStore, setNewStore] = useState({ name: "", email: "", address: "" }); const [newUser, setNewUser] = useState({ name: "", email: "", address: "", password: "", role: "user" as Role });
  const peopleShown = useMemo(() => people.filter(person => (role === "all" || person.role === role) && `${person.name} ${person.email} ${person.address}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sortAsc ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name)), [people, role, query, sortAsc]);
  const storesShown = useMemo(() => stores.filter(store => `${store.name} ${store.email} ${store.address}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sortAsc ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name)), [stores, query, sortAsc]);
  const addStore = (event: React.FormEvent) => { event.preventDefault(); if (!newStore.name || !newStore.email || !newStore.address) return toast("Complete all store fields first."); setStores(current => [{ ...newStore, id: Date.now(), rating: 0, ratingCount: 0, category: "New listing" }, ...current]); setNewStore({ name: "", email: "", address: "" }); setModal(null); toast("Store added to the directory."); };
  const addUser = (event: React.FormEvent) => { event.preventDefault(); const passwordError = validatePassword(newUser.password); if (newUser.name.trim().length < 20) return toast("Name must be between 20 and 60 characters."); if (passwordError) return toast(passwordError); setPeople(current => [{ ...newUser, id: Date.now(), initials: initials(newUser.name) }, ...current]); setNewUser({ name: "", email: "", address: "", password: "", role: "user" }); setModal(null); toast("User created successfully."); };
  return <div className="space-y-6 animate-float-in"><PageHeading eyebrow="Directory management" title={tab === "stores" ? "Store directory" : "People directory"} copy={tab === "stores" ? "Review every registered location, its contact details, and community signal." : "Manage access levels and keep the RatingsHub community organized."} action={<div className="flex gap-2"><Button variant="outline" onClick={() => setModal(tab === "stores" ? "store" : "user")}><Plus size={15} /> Add {tab === "stores" ? "store" : "user"}</Button></div>} /><div className="flex items-center justify-between gap-3 border-b border-[#E6E9E7]"><div className="flex gap-6">{[{label:"Stores",value:"stores" as const},{label:"People",value:"people" as const}].map(item => <button key={item.value} onClick={() => { setTab(item.value); setQuery(""); }} className={`relative pb-3 text-sm font-bold ${tab === item.value ? "text-[#C84F38]" : "text-[#84909D]"}`}>{item.label}<span className="ml-2 rounded-full bg-[#F1F3F2] px-1.5 py-0.5 text-[10px]">{item.value === "stores" ? stores.length : people.length}</span>{tab === item.value && <span className="absolute inset-x-0 -bottom-px h-0.5 bg-[#E86B4F]" />}</button>)}</div><div className="hidden items-center gap-2 text-xs text-[#A0A9B1] sm:flex"><Filter size={14} /> Smart filters</div></div><div className="flex flex-col gap-3 md:flex-row"><div className="relative flex-1"><Search size={16} className="absolute left-3.5 top-3.5 text-[#A1ACB6]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder={`Search by name, email or address...`} className="h-11 w-full rounded-xl border border-[#E0E5E6] bg-white pl-10 pr-4 text-sm outline-none focus:border-[#E86B4F] focus:ring-4 focus:ring-[#E86B4F]/10" /></div>{tab === "people" && <select value={role} onChange={e => setRole(e.target.value as typeof role)} className="h-11 rounded-xl border border-[#E0E5E6] bg-white px-3 text-sm font-semibold text-[#637084] outline-none"><option value="all">All roles</option><option value="user">Normal user</option><option value="admin">Administrator</option><option value="storeOwner">Store owner</option></select>}<Button variant="outline" onClick={() => setSortAsc(!sortAsc)}><span className="hidden sm:inline">Sort</span>{sortAsc ? <ArrowDownAZ size={16} /> : <ArrowUpAZ size={16} />}</Button></div><div className="overflow-hidden rounded-2xl border border-[#E6E9E7] bg-white shadow-[0_10px_30px_rgba(23,34,53,.035)]"><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead className="bg-[#F7F8F7]"><tr className="text-[10px] font-bold uppercase tracking-[.14em] text-[#9BA5AE]"><th className="px-5 py-3.5">{tab === "stores" ? "Store" : "Person"}</th><th className="px-5 py-3.5">Email</th><th className="px-5 py-3.5">Address</th><th className="px-5 py-3.5">{tab === "stores" ? "Community rating" : "Role"}</th><th className="px-5 py-3.5 text-right">Details</th></tr></thead><tbody className="divide-y divide-[#EEF0EF]">{tab === "stores" ? storesShown.map(store => <tr key={store.id} className="text-sm hover:bg-[#FCFCFB]"><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#FFF0EB] text-[#C84F38]"><Store size={16} /></div><div><div className="font-bold text-[#172235]">{store.name}</div><div className="mt-0.5 text-[10px] text-[#A0AAB3]">{store.category}</div></div></div></td><td className="px-5 py-4 text-xs text-[#667488]">{store.email}</td><td className="px-5 py-4 text-xs text-[#667488]"><div className="flex items-center gap-1.5"><MapPin size={13} className="text-[#A2ADB4]" />{store.address}</div></td><td className="px-5 py-4"><div className="flex items-center gap-2"><Stars value={Math.round(store.rating)} size={13} /><span className="text-xs font-bold">{store.rating ? store.rating.toFixed(1) : "—"}</span><span className="text-[10px] text-[#9BA5AE]">({store.ratingCount})</span></div></td><td className="px-5 py-4 text-right"><button className="rounded-lg p-2 text-[#96A1AE] hover:bg-[#F3F5F4] hover:text-[#172235]" onClick={() => toast(`${store.name} is a ${store.category.toLowerCase()} listing.`)}><ChevronRight size={16} /></button></td></tr>) : peopleShown.map(person => <tr key={person.id} className="text-sm hover:bg-[#FCFCFB]"><td className="px-5 py-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-full bg-[#E8EDF1] text-[11px] font-bold text-[#526277]">{person.initials}</div><div className="font-bold text-[#172235]">{person.name}</div></div></td><td className="px-5 py-4 text-xs text-[#667488]">{person.email}</td><td className="px-5 py-4 text-xs text-[#667488]">{person.address}</td><td className="px-5 py-4"><RolePill role={person.role} /></td><td className="px-5 py-4 text-right"><button className="rounded-lg p-2 text-[#96A1AE] hover:bg-[#F3F5F4] hover:text-[#172235]" onClick={() => setSelected(person)}><ChevronRight size={16} /></button></td></tr>)}{((tab === "stores" && storesShown.length === 0) || (tab === "people" && peopleShown.length === 0)) && <tr><td colSpan={5} className="px-5 py-12 text-center text-sm text-[#8D99A6]">No matches found. Try a broader search.</td></tr>}</tbody></table></div></div>{modal && <div className="fixed inset-0 z-40 grid place-items-center bg-[#172235]/30 p-4 backdrop-blur-sm"><div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#E86B4F]">New record</div><h2 className="font-display text-xl font-bold">Add {modal === "store" ? "a store" : "a user"}</h2></div><button onClick={() => setModal(null)} className="rounded-lg p-1 text-[#9BA6AF] hover:bg-[#F4F5F4]"><X size={18} /></button></div>{modal === "store" ? <form onSubmit={addStore} className="mt-6 space-y-4"><Field label="Store name" value={newStore.name} onChange={value => setNewStore({ ...newStore, name: value })} placeholder="e.g. The Greenhouse" required /><Field label="Store email" value={newStore.email} onChange={value => setNewStore({ ...newStore, email: value })} placeholder="hello@store.com" type="email" required /><Field label="Address" value={newStore.address} onChange={value => setNewStore({ ...newStore, address: value })} placeholder="Street, city, state" required /><div className="flex justify-end gap-2 pt-2"><Button variant="ghost" onClick={() => setModal(null)}>Cancel</Button><Button type="submit">Add store</Button></div></form> : <form onSubmit={addUser} className="mt-6 grid gap-4 sm:grid-cols-2"><div className="sm:col-span-2"><Field label="Full name" value={newUser.name} onChange={value => setNewUser({ ...newUser, name: value })} placeholder="20–60 characters" required /></div><Field label="Email" value={newUser.email} onChange={value => setNewUser({ ...newUser, email: value })} placeholder="person@example.com" type="email" required /><Field label="Password" value={newUser.password} onChange={value => setNewUser({ ...newUser, password: value })} placeholder="Uppercase + special" type="password" required /><div className="sm:col-span-2"><Field label="Address" value={newUser.address} onChange={value => setNewUser({ ...newUser, address: value })} placeholder="Street, city, state" required /></div><label className="sm:col-span-2"><span className="mb-1.5 block text-xs font-bold text-[#46546A]">Role</span><select value={newUser.role} onChange={e => setNewUser({ ...newUser, role: e.target.value as Role })} className="h-11 w-full rounded-xl border border-[#DFE4E6] bg-white px-3.5 text-sm font-semibold outline-none focus:border-[#E86B4F]"><option value="user">Normal user</option><option value="admin">Administrator</option><option value="storeOwner">Store owner</option></select></label><div className="flex justify-end gap-2 pt-2 sm:col-span-2"><Button variant="ghost" onClick={() => setModal(null)}>Cancel</Button><Button type="submit">Create user</Button></div></form>}</div></div>}{selected && <div className="fixed inset-0 z-40 grid place-items-center bg-[#172235]/30 p-4 backdrop-blur-sm"><div className="w-full max-w-sm rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#E8EDF1] font-display font-bold text-[#526277]">{selected.initials}</div><button onClick={() => setSelected(null)} className="rounded-lg p-1 text-[#9BA6AF]"><X size={18} /></button></div><h2 className="mt-5 font-display text-xl font-bold">{selected.name}</h2><div className="mt-2"><RolePill role={selected.role} /></div><div className="mt-5 space-y-3 border-t border-[#EEF0EF] pt-4 text-sm"><div className="flex gap-3"><Mail size={16} className="mt-0.5 text-[#A1ADB7]" /><span className="text-[#667488]">{selected.email}</span></div><div className="flex gap-3"><MapPin size={16} className="mt-0.5 text-[#A1ADB7]" /><span className="text-[#667488]">{selected.address}</span></div></div><Button className="mt-6 w-full" onClick={() => setSelected(null)}>Done</Button></div></div>}</div>;
}

function UserDashboard({ stores, ratings, setRatings, toast }: { stores: StoreRecord[]; ratings: Record<number, number>; setRatings: React.Dispatch<React.SetStateAction<Record<number, number>>>; toast: (message: string) => void }) {
  const [query, setQuery] = useState(""); const [category, setCategory] = useState("All categories"); const [selected, setSelected] = useState<StoreRecord | null>(null); const [draftRating, setDraftRating] = useState(0);
  const categories = ["All categories", ...Array.from(new Set(stores.map(store => store.category)))]; const visible = stores.filter(store => (category === "All categories" || store.category === category) && `${store.name} ${store.address}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="space-y-6 animate-float-in"><PageHeading eyebrow="Normal user" title="Find your next favorite" copy="Browse registered stores, see the community signal, and leave a rating that helps someone decide." /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Stores explored" value={String(stores.length)} detail="Across 8 categories" icon={Store} accent="coral" /><StatCard label="Your ratings" value={String(Object.keys(ratings).length)} detail="Keep your signal fresh" icon={Star} accent="teal" /><StatCard label="Average you gave" value={Object.keys(ratings).length ? (Object.values(ratings).reduce((a, b) => a + b, 0) / Object.keys(ratings).length).toFixed(1) : "—"} detail="Based on your submissions" icon={BarChart3} accent="blue" /></div><div className="flex flex-col gap-3 md:flex-row"><div className="relative flex-1"><Search size={17} className="absolute left-3.5 top-3.5 text-[#A1ACB6]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search stores by name or address..." className="h-12 w-full rounded-xl border border-[#E0E5E6] bg-white pl-10 pr-4 text-sm outline-none focus:border-[#E86B4F] focus:ring-4 focus:ring-[#E86B4F]/10" /></div><select value={category} onChange={e => setCategory(e.target.value)} className="h-12 rounded-xl border border-[#E0E5E6] bg-white px-4 text-sm font-bold text-[#637084] outline-none"><option>{categories[0]}</option>{categories.slice(1).map(item => <option key={item}>{item}</option>)}</select></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{visible.map(store => <div key={store.id} className="group rounded-2xl border border-[#E6E9E7] bg-white p-5 shadow-[0_10px_30px_rgba(23,34,53,.035)] transition hover:-translate-y-0.5 hover:shadow-[0_14px_36px_rgba(23,34,53,.08)]"><div className="flex items-start justify-between"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-[#FFF0EB] text-[#C84F38]"><Store size={19} /></div><span className="rounded-full bg-[#F4F6F5] px-2.5 py-1 text-[10px] font-bold text-[#778496]">{store.category}</span></div><h3 className="mt-5 font-display text-lg font-bold tracking-[-.02em]">{store.name}</h3><div className="mt-1 flex items-start gap-1.5 text-xs text-[#8A96A5]"><MapPin size={13} className="mt-0.5 shrink-0" />{store.address}</div><div className="mt-5 flex items-center justify-between border-t border-[#EEF0EF] pt-4"><div><div className="flex items-center gap-2"><Stars value={Math.round(store.rating)} size={14} /><span className="text-sm font-bold">{store.rating.toFixed(1)}</span></div><div className="mt-1 text-[10px] text-[#A0AAB3]">{store.ratingCount} community ratings</div></div><button onClick={() => { setSelected(store); setDraftRating(ratings[store.id] ?? 0); }} className={`rounded-xl px-3 py-2 text-xs font-bold ${ratings[store.id] ? "bg-[#EAF5F1] text-[#167469]" : "bg-[#172235] text-white"}`}>{ratings[store.id] ? "Edit rating" : "Rate store"}</button></div></div>)}{visible.length === 0 && <div className="rounded-2xl border border-dashed border-[#CBD4D6] bg-white px-5 py-14 text-center md:col-span-2 xl:col-span-3"><Search size={24} className="mx-auto text-[#B1BBC2]" /><div className="mt-3 font-display font-bold">No stores match that search</div><div className="mt-1 text-sm text-[#8A96A5]">Try a different name, address, or category.</div></div>}</div>{selected && <div className="fixed inset-0 z-40 grid place-items-center bg-[#172235]/30 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.18em] text-[#E86B4F]">Community rating</div><h2 className="font-display text-2xl font-bold">{selected.name}</h2><p className="mt-1 text-sm text-[#8792A0]">How was your experience?</p></div><button onClick={() => setSelected(null)} className="rounded-lg p-1 text-[#9BA6AF]"><X size={18} /></button></div><div className="mt-7 rounded-2xl bg-[#FAF7F4] p-5 text-center"><div className="text-[11px] font-bold uppercase tracking-[.14em] text-[#A28E86]">Your rating</div><div className="mt-4 flex justify-center"><Stars value={draftRating} onChange={setDraftRating} size={29} /></div><div className="mt-3 text-xs font-semibold text-[#8B8F94]">{draftRating ? `${draftRating} out of 5` : "Select a rating"}</div></div><div className="mt-5 flex gap-2"><Button variant="ghost" className="flex-1" onClick={() => setSelected(null)}>Cancel</Button><Button className="flex-1" disabled={!draftRating} onClick={() => { setRatings(current => ({ ...current, [selected.id]: draftRating })); setSelected(null); toast(ratings[selected.id] ? "Your rating was updated." : "Thanks — your rating was submitted."); }}>Save rating <Check size={15} /></Button></div></div></div>}</div>;
}

function Activity({ stores, ratings }: { stores: StoreRecord[]; ratings: Record<number, number> }) {
  const ratedStores = stores.filter(store => ratings[store.id]);
  return <div className="space-y-6 animate-float-in"><PageHeading eyebrow="Your activity" title="Your rating trail" copy="A simple history of the places you have helped shape with feedback." /><div className="rounded-2xl border border-[#E6E9E7] bg-white shadow-[0_10px_30px_rgba(23,34,53,.035)]"><div className="border-b border-[#EEF0EF] p-5"><h2 className="font-display font-bold">Submitted ratings</h2><p className="mt-1 text-xs text-[#8A96A5]">You can edit any rating from Discover stores.</p></div>{ratedStores.length ? <div className="divide-y divide-[#EEF0EF]">{ratedStores.map(store => <div key={store.id} className="flex items-center gap-4 p-5"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#FFF0EB] text-[#C84F38]"><Store size={17} /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-bold">{store.name}</div><div className="mt-1 truncate text-xs text-[#8A96A5]">{store.address}</div></div><div className="text-right"><Stars value={ratings[store.id]} size={14} /><div className="mt-1 text-[10px] font-bold text-[#A1ABB3]">Your rating</div></div></div>)}</div> : <div className="px-5 py-14 text-center text-sm text-[#8A96A5]">Your submitted ratings will appear here.</div>}</div></div>;
}

function OwnerDashboard({ stores, ratings }: { stores: StoreRecord[]; ratings: Record<number, number> }) {
  const ownStore = stores[0]; const average = ownStore.rating; const reviewRows = [{ name: "Alex Morgan", email: "alex@ratingshub.io", rating: 5, date: "Today, 9:42 AM" }, { name: "Samira Williams", email: "samira@ratingshub.io", rating: 5, date: "Yesterday" }, { name: "Theo Benjamin", email: "theo@ratingshub.io", rating: 4, date: "Sep 26, 2026" }, { name: "Priya Shah", email: "priya@ratingshub.io", rating: 5, date: "Sep 25, 2026" }];
  return <div className="space-y-6 animate-float-in"><PageHeading eyebrow="Store owner" title="Your store, in focus" copy="See the signal behind your storefront and the people taking time to share it." action={<Button variant="outline"><Settings size={15} /> Store settings</Button>} /><div className="rounded-2xl bg-[#172235] p-6 text-white shadow-[0_12px_32px_rgba(23,34,53,.12)] sm:p-7"><div className="flex flex-col justify-between gap-6 sm:flex-row sm:items-end"><div><div className="mb-3 inline-flex items-center gap-2 rounded-full bg-white/10 px-3 py-1.5 text-[10px] font-bold uppercase tracking-[.14em] text-[#B6C2D0]"><Store size={13} /> Your featured listing</div><h2 className="font-display text-3xl font-bold tracking-[-.04em]">{ownStore.name}</h2><div className="mt-2 flex items-center gap-2 text-sm text-[#9DAABA]"><MapPin size={14} />{ownStore.address}</div></div><div className="sm:text-right"><div className="flex items-center gap-3 sm:justify-end"><span className="font-display text-5xl font-bold tracking-[-.06em]">{average.toFixed(1)}</span><div><Stars value={Math.round(average)} size={18} /><div className="mt-1 text-xs text-[#9DAABA]">out of 5.0</div></div></div><div className="mt-2 text-xs text-[#9DAABA]">{ownStore.ratingCount} community ratings</div></div></div></div><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Average rating" value={average.toFixed(1)} trend="+0.2" detail="vs. last month" icon={Star} accent="coral" /><StatCard label="Ratings received" value={String(ownStore.ratingCount)} trend="+14%" detail="Across all time" icon={ClipboardList} accent="teal" /><StatCard label="Response health" value="92%" detail="Positive rating share" icon={BarChart3} accent="blue" /></div><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><section className="rounded-2xl border border-[#E6E9E7] bg-white shadow-[0_10px_30px_rgba(23,34,53,.035)]"><div className="flex items-center justify-between border-b border-[#EEF0EF] p-5"><div><h2 className="font-display font-bold">Recent reviewers</h2><p className="mt-1 text-xs text-[#8A96A5]">People who submitted a rating</p></div><button className="text-xs font-bold text-[#C84F38]">View all</button></div><div className="divide-y divide-[#EEF0EF]">{reviewRows.map(row => <div key={row.email} className="flex items-center gap-3 p-4 sm:p-5"><div className="grid h-9 w-9 place-items-center rounded-full bg-[#E8EDF1] text-[10px] font-bold text-[#526277]">{initials(row.name)}</div><div className="min-w-0 flex-1"><div className="text-xs font-bold">{row.name}</div><div className="mt-0.5 truncate text-[10px] text-[#9AA4AF]">{row.email}</div></div><div className="hidden text-right sm:block"><div className="text-[10px] text-[#A1ABB3]">{row.date}</div><div className="mt-1 flex justify-end"><Stars value={row.rating} size={13} /></div></div><div className="text-right sm:hidden"><Stars value={row.rating} size={13} /></div></div>)}</div></section><section className="rounded-2xl border border-[#E6E9E7] bg-white p-5 shadow-[0_10px_30px_rgba(23,34,53,.035)]"><div><h2 className="font-display font-bold">What is working</h2><p className="mt-1 text-xs text-[#8A96A5]">A quick read on your signal</p></div><div className="mt-6 space-y-5"><div><div className="flex items-center justify-between text-xs"><span className="font-bold text-[#637084]">5-star ratings</span><span className="font-bold">72%</span></div><div className="mt-2 h-2 rounded-full bg-[#EEF1F1]"><div className="h-full w-[72%] rounded-full bg-[#E86B4F]" /></div></div><div><div className="flex items-center justify-between text-xs"><span className="font-bold text-[#637084]">4-star ratings</span><span className="font-bold">19%</span></div><div className="mt-2 h-2 rounded-full bg-[#EEF1F1]"><div className="h-full w-[19%] rounded-full bg-[#F6B59F]" /></div></div><div><div className="flex items-center justify-between text-xs"><span className="font-bold text-[#637084]">1–3 star ratings</span><span className="font-bold">9%</span></div><div className="mt-2 h-2 rounded-full bg-[#EEF1F1]"><div className="h-full w-[9%] rounded-full bg-[#BFC8CD]" /></div></div></div><div className="mt-8 rounded-xl bg-[#EAF5F1] p-4"><div className="flex gap-2.5"><Sparkles size={16} className="mt-0.5 text-[#167469]" /><div><div className="text-xs font-bold text-[#167469]">Strong signal</div><div className="mt-1 text-[11px] leading-5 text-[#52867D]">Your store is in the top 8% of listings this month.</div></div></div></div></section></div></div>;
}

function SettingsPage({ user, toast }: { user: AppUser; toast: (message: string) => void }) {
  const [password, setPassword] = useState(""); const [confirm, setConfirm] = useState(""); const [error, setError] = useState(""); const save = (event: React.FormEvent) => { event.preventDefault(); const passwordError = validatePassword(password); if (passwordError) return setError(passwordError); if (password !== confirm) return setError("Passwords do not match."); setError(""); setPassword(""); setConfirm(""); toast("Password updated securely."); };
  return <div className="max-w-3xl space-y-6 animate-float-in"><PageHeading eyebrow="Account settings" title="Your account" copy="Manage the essentials of your RatingsHub profile and sign-in security." /><section className="rounded-2xl border border-[#E6E9E7] bg-white p-5 shadow-[0_10px_30px_rgba(23,34,53,.035)] sm:p-6"><div className="flex items-center gap-4 border-b border-[#EEF0EF] pb-5"><div className="grid h-14 w-14 place-items-center rounded-2xl bg-[#172235] font-display font-bold text-white">{user.initials}</div><div><h2 className="font-display text-lg font-bold">{user.name}</h2><div className="mt-1 text-sm text-[#8A96A5]">{user.email}</div><div className="mt-2"><RolePill role={user.role} /></div></div></div><div className="grid gap-5 pt-5 sm:grid-cols-2"><div><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#9DA7B0]">Address</div><div className="mt-2 text-sm font-semibold text-[#536176]">{user.address}</div></div><div><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#9DA7B0]">Access level</div><div className="mt-2 text-sm font-semibold text-[#536176]">{user.role === "admin" ? "System administrator" : user.role === "storeOwner" ? "Store owner" : "Normal user"}</div></div></div></section><section className="rounded-2xl border border-[#E6E9E7] bg-white p-5 shadow-[0_10px_30px_rgba(23,34,53,.035)] sm:p-6"><div className="flex items-start gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#EEF2FF] text-[#5267B9]"><KeyRound size={17} /></div><div><h2 className="font-display font-bold">Change password</h2><p className="mt-1 text-xs leading-5 text-[#8A96A5]">Use 8–16 characters with an uppercase letter and special character.</p></div></div><form onSubmit={save} className="mt-5 max-w-lg space-y-4"><Field label="New password" value={password} onChange={setPassword} placeholder="New secure password" type="password" required /><Field label="Confirm password" value={confirm} onChange={setConfirm} placeholder="Repeat new password" type="password" required />{error && <div className="rounded-xl bg-[#FFF2EF] px-3 py-2 text-xs font-semibold text-[#C84F38]">{error}</div>}<Button type="submit">Update password</Button></form></section></div>;
}

export default function Home() {
  const [user, setUser] = useState<AppUser | null>(() => { try { const raw = localStorage.getItem("ratingshub-user"); return raw ? JSON.parse(raw) : null; } catch { return null; } });
  const [view, setView] = useState<View>(() => user?.role === "user" ? "discover" : "overview"); const [stores, setStores] = useState(starterStores); const [people, setPeople] = useState(starterPeople); const [ratings, setRatings] = useState<Record<number, number>>(() => { try { const raw = localStorage.getItem("ratingshub-ratings"); return raw ? JSON.parse(raw) : startingRatings; } catch { return startingRatings; } }); const [mobileOpen, setMobileOpen] = useState(false); const [toastMessage, setToastMessage] = useState("");
  useEffect(() => { if (user) localStorage.setItem("ratingshub-user", JSON.stringify(user)); else localStorage.removeItem("ratingshub-user"); }, [user]); useEffect(() => { localStorage.setItem("ratingshub-ratings", JSON.stringify(ratings)); }, [ratings]); useEffect(() => { if (!toastMessage) return; const timer = window.setTimeout(() => setToastMessage(""), 3000); return () => window.clearTimeout(timer); }, [toastMessage]);
  const login = (next: AppUser) => { setUser(next); setView(next.role === "user" ? "discover" : "overview"); }; const logout = () => { setUser(null); setMobileOpen(false); }; const toast = (message: string) => setToastMessage(message);
  if (!user) return <AuthScreen onLogin={login} />;
  return <div className="flex min-h-screen bg-[#F8F7F4]"><Sidebar user={user} view={view} setView={setView} onLogout={logout} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} /><div className="min-w-0 flex-1"><Topbar user={user} onOpenMenu={() => setMobileOpen(true)} /><main className="mx-auto max-w-[1440px] px-5 py-7 sm:px-8 lg:px-10 lg:py-9">{user.role === "admin" && view === "overview" && <AdminOverview stores={stores} people={people} setView={setView} />}{user.role === "admin" && (view === "stores" || view === "people") && <AdminDirectory stores={stores} people={people} setStores={setStores} setPeople={setPeople} initialTab={view} toast={toast} />}{user.role === "user" && view === "discover" && <UserDashboard stores={stores} ratings={ratings} setRatings={setRatings} toast={toast} />}{user.role === "user" && view === "activity" && <Activity stores={stores} ratings={ratings} />}{user.role === "storeOwner" && (view === "overview" || view === "reviews") && <OwnerDashboard stores={stores} ratings={ratings} />}{view === "settings" && <SettingsPage user={user} toast={toast} />}</main></div>{toastMessage && <div className="fixed bottom-5 right-5 z-50 flex items-center gap-2 rounded-xl bg-[#172235] px-4 py-3 text-sm font-bold text-white shadow-2xl"><Check size={16} className="text-[#8DD2BE]" />{toastMessage}</div>}</div>;
}
